scalar-output-selection.specification:
schema_version: '1.0'
domain: TEST
base: SRC
keys: [ID]
input:
  SRC: {path: input.csv}
output: {path: result.csv, columns: [ID, BASE, FIRST, LAST]}
columns:
  - {name: ID, type: str, derivation: SRC.ID}
  - {name: BASE, type: int, derivation: SRC.V}
  - {name: FIRST, type: int, derivation: {source: {variable: BASE, order_by: [SRC.ID], keep: first}}}
  - {name: LAST, type: int, derivation: {source: {variable: BASE, order_by: [SRC.ID], keep: last}}}

already-selected-intermediate.specification:
schema_version: '1.0'
domain: TEST
base: SRC
keys: [ID]
input:
  SRC: {path: input.csv}
  DONOR: {path: donor.csv, types: {SEQ: int}}
output: {path: result.csv, columns: [ID, A, B]}
intermediates:
  - id: P
    dataset: DONOR
    key: {ID: ID}
    order_by: [DONOR.SEQ]
    keep: first
    no_match: null
columns:
  - {name: ID, type: str, derivation: SRC.ID}
  - {name: A, type: str, derivation: {source: {variable: P.A, order_by: [DONOR.SEQ], keep: last}}}
  - {name: B, type: str, derivation: {source: {variable: P.B, order_by: [DONOR.SEQ], keep: first, absent: fallback}}}

