named-key-candidates-choice.specification:
schema_version: '1.0'
domain: TEST
base: SRC
keys: [ID, A, B]
input:
  SRC: {path: input.csv, types: {CUT: int}}
  DONOR: {path: donor.csv, types: {SEQ: int}}
output: {path: result.csv, columns: [ID, A, B, C]}
intermediates:
  - id: P
    dataset: DONOR
    key: {ID: ID}
    filter: 'DONOR.SEQ > SRC.CUT'
    order_by: [DONOR.SEQ]
    keep: first
    no_match: null
columns:
  - {name: ID, type: str, derivation: SRC.ID}
  - {name: A, type: str, derivation: {first_available: {sources: [P.A, SRC.BACKUP]}}}
  - {name: B, type: str, derivation: {source: {variable: P.B, order_by: [DONOR.SEQ], keep: last}}}
  - {name: C, type: str, derivation: P.C}

